// IMPORTAR
const fs = require('fs');

// LÊ E CONVERTE O ARQUIVO JSON PARA ARRAY DE OBJETOS
const texto = fs.readFileSync('monitoramento.json', 'utf-8');
const sensores = JSON.parse(texto);


console.log("=== TODOS OS SENSORES ===");


for (let sensor of sensores) {
  console.log(`[${sensor.codigo}] ${sensor.tipo}: ${sensor.valor} ${sensor.unidade} - Status: ${sensor.status}`);
}


let totalAlerta = 0;


console.log("\n=== SENSORES EM ALERTA ===");


for (let sensor of sensores) {

  // VERIFICA SE O STATUS É IGUAL A ALERTA
  if (sensor.status === "Alerta") {
    console.log(`[${sensor.codigo}] ${sensor.tipo}: ${sensor.valor} ${sensor.unidade}`);
    totalAlerta++; // SOMA +1 NO CONTADOR DE ALERTAS
  }

}


console.log(`\nTotal de sensores em alerta: ${totalAlerta}`);


//   ==================================================================
//   RESUMO DOS COMANDOS USADOS:
//   ==================================================================

//   1. fs.readFileSync() E JSON.parse():
//      - Lê o texto do arquivo e converte de volta em lista (array).

//   2. COMPARADOR DE TEXTO (sensor.status === "Alerta"):
//      - Compara se a propriedade status do sensor é a palavra "Alerta".

//   3. CONTADOR (totalAlerta++):
//      - Soma 1 cada vez que entra no 'if' quando encontra um alerta.